// How many precache downloads run in parallel. Kept low so a background
// precache never starves the game's own asset requests.
const PRECACHE_CONCURRENCY = 4;

// Skip dev-server API endpoints — never cache them.
const SKIP_PATTERNS = [
  /\/__ui-editor\//,
  /\/__car-editor\//,
  /\/__enemy-editor\//,
  /\/__designer\//,
];

self.addEventListener('install', () => {
  // No precache here: downloading everything during install competes with the
  // game's initial load. The page triggers precache later (see message below).
  self.skipWaiting();
});

self.addEventListener('activate', (event) => {
  // Delete caches from previous versions.
  event.waitUntil(
    caches.keys()
      .then((keys) => Promise.all(keys.filter((k) => k !== CACHE_NAME).map((k) => caches.delete(k))))
      .then(() => self.clients.claim()),
  );
});

// Deferred precache: the page posts {type:'precache'} once the game has
// finished its own loading. Fetches only URLs not already in the cache
// (requests made during normal play land in the cache via the fetch handler).
let precacheStarted = false;
self.addEventListener('message', (event) => {
  if (event.data?.type !== 'precache' || precacheStarted) return;
  precacheStarted = true;
  event.waitUntil(precacheAll());
});

async function precacheAll() {
  const cache = await caches.open(CACHE_NAME);
  const queue = [];
  for (const url of PRECACHE_URLS) {
    const hit = await cache.match(url);
    if (!hit) queue.push(url);
  }
  let i = 0;
  const worker = async () => {
    while (i < queue.length) {
      const url = queue[i++];
      try {
        await cache.add(url);
      } catch { /* individual failures must not block the rest */ }
    }
  };
  await Promise.all(Array.from({ length: PRECACHE_CONCURRENCY }, worker));
}

self.addEventListener('fetch', (event) => {
  const { request } = event;
  if (request.method !== 'GET') return;

  const url = new URL(request.url);
  if (url.origin !== self.location.origin) return;
  if (SKIP_PATTERNS.some((p) => p.test(url.pathname))) return;

  // App shell (navigations) is network-first: cache-first here made deploys
  // serve a STALE index.html whose old hashed JS then 404'd on renamed assets.
  // Offline still works via the cached copy.
  // Designer-tunable configs (/balance/*.json) are network-first too — they are
  // re-uploaded to the host between builds and must never be pinned by cache.
  if (request.mode === 'navigate' || url.pathname.includes('/balance/')) {
    event.respondWith(
      fetch(request)
        .then((response) => {
          if (response.ok) {
            const clone = response.clone();
            caches.open(CACHE_NAME).then((cache) => cache.put(request, clone));
          }
          return response;
        })
        .catch(() => caches.match(request).then((c) => c || Response.error())),
    );
    return;
  }

  event.respondWith(
    caches.match(request).then((cached) => {
      if (cached) return cached;
      return fetch(request).then((response) => {
        if (response.ok) {
          const clone = response.clone();
          caches.open(CACHE_NAME).then((cache) => cache.put(request, clone));
        }
        return response;
      });
    }),
  );
});
